package com.thinking.ticket.adapter.out.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/* 티켓의 영속 모델. 도메인 Ticket과 일부러 다른 클래스로 둔다 — 도메인에 JPA 애노테이션이 붙는 순간
 * Core가 영속 기술을 알게 되고, 저장 스키마의 사정이 업무 규칙의 모양을 규정하게 된다.
 *
 * 물리 컬럼 이름을 @Column으로 못박는다. 스키마가 이 클래스로부터 만들어지는 구성이라,
 * 네이밍 전략 설정 하나만 바뀌어도 컬럼 이름이 조용히 달라져 저장 계약이 깨지기 때문이다. */
@Entity
@Table(name = "tickets")
public class TicketJpaEntity {

    /* 식별자는 도메인이 이미 정해 넘겨준다 — 여기서 생성 전략을 두면 저장 기술이 식별자를 소유하게 된다. */
    @Id
    @Column(name = "id")
    private Long id;

    @Column(name = "price", nullable = false)
    private int price;

    @Column(name = "reserved", nullable = false)
    private boolean reserved;

    @Column(name = "suspended", nullable = false)
    private boolean suspended;

    @Column(name = "user_id")
    private long userId;

    /* JPA가 리플렉션으로 쓰는 기본 생성자. 업무 코드가 빈 상태의 엔티티를 만들지 못하게 protected로 둔다. */
    protected TicketJpaEntity() {
    }

    public TicketJpaEntity(Long id, int price, boolean reserved, boolean suspended, long userId) {
        this.id = id;
        this.price = price;
        this.reserved = reserved;
        this.suspended = suspended;
        this.userId = userId;
    }

    public Long getId() {
        return id;
    }

    public int getPrice() {
        return price;
    }

    public boolean isReserved() {
        return reserved;
    }

    public boolean isSuspended() {
        return suspended;
    }

    public long getUserId() {
        return userId;
    }
}

package com.thinking.ticket.adapter.out.persistence;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

/* 저장 기술 쪽 인터페이스. Core의 TicketRepository(Port)와 이름이 비슷하지만 성격이 다르다 —
 * 이쪽은 어댑터 내부의 세부이고, 바깥으로 드러나는 계약은 Port 하나뿐이다.
 * 그래서 이 타입은 어댑터 밖(Core·다른 어댑터)에서 쓰지 않는다. */
public interface TicketJpaRepository extends JpaRepository<TicketJpaEntity, Long> {

    /* 예약 확정을 '아직 예약되지 않은 행'에만 적용하는 조건부 갱신.
     * 인스턴스가 여러 개면 두 요청이 같은 티켓을 각자 읽어 둘 다 예약 가능으로 판단할 수 있다.
     * 그때 읽은 상태를 통째로 쓰면 나중 쓰기가 먼저 확정된 예약을 덮어쓰므로,
     * 조건을 DB의 UPDATE 문 안으로 옮겨 그 창을 닫는다.
     * 갱신된 행 수가 판정 근거다 — 0이면 대상 행이 없거나 이미 예약됐다는 뜻이다. */
    @Modifying(clearAutomatically = true, flushAutomatically = true)
    @Query("update TicketJpaEntity t set t.reserved = true, t.userId = :userId "
            + "where t.id = :id and t.reserved = false")
    int reserveIfNotReserved(@Param("id") long id, @Param("userId") long userId);
}

package com.thinking.ticket.adapter.out.persistence;

import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

import com.thinking.ticket.core.domain.Ticket;
import com.thinking.ticket.core.port.out.TicketRepository;

/* Outbound Adapter: Core가 요구한 저장 계약(TicketRepository)을 JPA + MySQL로 구현한다.
 * 도메인 ↔ 영속 모델 변환도 이 안에서 끝낸다 — 변환이 밖으로 새면 영속 모델이 Core까지 흘러간다.
 * 스프링 빈으로 등록해 두어야 조립 지점이 이 구현을 포트 자리에 꽂을 수 있다. */
@Repository
public class TicketPersistenceAdapter implements TicketRepository {

    private final TicketJpaRepository ticketJpaRepository;

    public TicketPersistenceAdapter(TicketJpaRepository ticketJpaRepository) {
        this.ticketJpaRepository = ticketJpaRepository;
    }

    @Override
    public Ticket findById(long ticketId) {
        /* 없으면 null을 준다. '없음'을 어떤 예외로 볼지는 유스케이스의 판단이라 저장 기술이 정하지 않는다. */
        return ticketJpaRepository.findById(ticketId)
                .map(this::toDomain)
                .orElse(null);
    }

    @Override
    @Transactional
    public void save(Ticket ticket) {
        if (!ticket.isReserved()) {
            ticketJpaRepository.save(toEntity(ticket));
            return;
        }

        /* 예약 확정만은 조건부 갱신으로 쓴다. 상태 전체를 그대로 덮어쓰면
         * 다른 인스턴스가 먼저 확정한 예약이 소리 없이 지워진다. */
        int updated = ticketJpaRepository.reserveIfNotReserved(ticket.getId(), ticket.getUserId());
        if (updated == 1) {
            return;
        }

        if (!ticketJpaRepository.existsById(ticket.getId())) {
            /* 아직 저장된 적 없는 예약 상태 티켓 — 갱신할 행이 없어서 0이었을 뿐이므로 그대로 넣는다. */
            ticketJpaRepository.save(toEntity(ticket));
            return;
        }

        /* 행은 있는데 갱신되지 않았다 = 그 사이 다른 예약이 먼저 확정됐다.
         * 스프링 표준 낙관적 잠금 예외로 알린다 — 진입 어댑터가 프로토콜 응답으로 번역할 수 있는 신호다. */
        throw new OptimisticLockingFailureException("이미 예약된 티켓이다: ticketId=" + ticket.getId());
    }

    private Ticket toDomain(TicketJpaEntity entity) {
        return Ticket.rehydrate(entity.getId(), entity.getPrice(), entity.isReserved(),
                entity.isSuspended(), entity.getUserId());
    }

    private TicketJpaEntity toEntity(Ticket ticket) {
        return new TicketJpaEntity(ticket.getId(), ticket.getPrice(), ticket.isReserved(),
                ticket.isSuspended(), ticket.getUserId());
    }
}

package com.thinking.ticket.adapter.out.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/* 회원의 영속 모델. 도메인 User가 지금은 데이터 그릇에 가깝지만 여기서도 분리를 유지한다 —
 * 한쪽만 겸용으로 두면 경계가 반쪽이 되고, 나중에 회원에 규칙이 생겼을 때 되돌리기 어렵다. */
@Entity
@Table(name = "users")
public class UserJpaEntity {

    @Id
    @Column(name = "id")
    private Long id;

    @Column(name = "name")
    private String name;

    /* JPA가 리플렉션으로 쓰는 기본 생성자. */
    protected UserJpaEntity() {
    }

    public UserJpaEntity(Long id, String name) {
        this.id = id;
        this.name = name;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }
}

package com.thinking.ticket.adapter.out.persistence;

import org.springframework.data.jpa.repository.JpaRepository;

/* 회원 조회용 저장 기술 인터페이스. 어댑터 내부 세부이므로 이 패키지 밖에서 쓰지 않는다. */
public interface UserJpaRepository extends JpaRepository<UserJpaEntity, Long> {
}

package com.thinking.ticket.adapter.out.persistence;

import org.springframework.stereotype.Repository;

import com.thinking.ticket.core.domain.User;
import com.thinking.ticket.core.port.out.UserRepository;

/* Outbound Adapter: Core가 요구한 회원 조회 계약(UserRepository)을 JPA + MySQL로 구현한다. */
@Repository
public class UserPersistenceAdapter implements UserRepository {

    private final UserJpaRepository userJpaRepository;

    public UserPersistenceAdapter(UserJpaRepository userJpaRepository) {
        this.userJpaRepository = userJpaRepository;
    }

    @Override
    public User findById(long userId) {
        /* 없으면 null. 자격 없는 요청을 어떻게 다룰지는 유스케이스가 정한다. */
        return userJpaRepository.findById(userId)
                .map(this::toDomain)
                .orElse(null);
    }

    private User toDomain(UserJpaEntity entity) {
        return new User(entity.getId(), entity.getName());
    }
}

package com.thinking.ticket.adapter.out.payment;

import java.net.URI;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClientException;
import org.springframework.web.client.RestTemplate;

import com.thinking.ticket.core.port.out.ChargePort;

/* Outbound Adapter: Core가 요구한 청구 계약(ChargePort)을 외부 결제사 HTTP 호출로 구현한다.
 * 결제사 주소가 환경마다 다르다는 사실은 이 층의 사정이므로 설정값으로 받아 여기서만 안다 —
 * Core는 '청구해 달라'까지만 안다.
 *
 * 스프링 빈으로 등록해 두어야 조립 지점이 이 구현을 포트 자리에 꽂을 수 있다. */
@Component
public class PgChargeAdapter implements ChargePort {

    private final RestTemplate restTemplate;
    private final URI chargeUri;

    public PgChargeAdapter(@Value("${pg.base-url}") String baseUrl) {
        /* HTTP 클라이언트는 이 어댑터의 내부 세부다. 교체 축이 없어 인터페이스로 뽑지 않고,
         * 생성자 시그니처에도 드러내지 않는다. */
        this.restTemplate = new RestTemplate();
        this.chargeUri = URI.create(stripTrailingSlash(baseUrl) + "/payments");
    }

    @Override
    public boolean charge(String paymentInfo, int amount) {
        try {
            ResponseEntity<Void> response = restTemplate.postForEntity(
                    chargeUri, new PgChargeRequest(paymentInfo, amount), Void.class);
            return response.getStatusCode().is2xxSuccessful();
        } catch (RestClientException e) {
            /* 통신 실패와 승인 거절을 구분해 알릴 자리가 계약(boolean)에 없다. 여기서 임의의 예외를
             * 만들어 던지면 Core가 결제 기술의 실패 모양을 알게 되므로, '청구되지 않았다'로만 답한다. */
            return false;
        }
    }

    /* 설정값이 슬래시로 끝나도 경로가 이중 슬래시가 되지 않게 맞춘다. */
    private static String stripTrailingSlash(String baseUrl) {
        return baseUrl.endsWith("/") ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
    }
}

package com.thinking.ticket.adapter.out.payment;

/* 결제사에 보내는 요청 본문. 도메인 개념이 아니라 이 어댑터와 결제사 사이의 전송 모양이라
 * 패키지 밖으로 내보내지 않는다. */
record PgChargeRequest(String paymentInfo, int amount) {
}
